mapper.insert:
INSERT INTO im_group_summary
    (group_id, requester_id, first_message_id, last_message_id, content)
SELECT #{groupId}, #{requesterId}, #{firstMessageId}, #{lastMessageId}, #{content}
FROM im_group_member
WHERE group_id = #{groupId} AND user_id = #{requesterId}
  AND joined_after_id < #{firstMessageId}

mapper.select:
SELECT s.id, s.group_id, s.requester_id, s.first_message_id, s.last_message_id,
       s.content, s.created_at
FROM im_group_summary s
JOIN im_group_member gm ON gm.group_id = s.group_id AND gm.user_id = #{userId}
WHERE s.id = #{id} AND s.group_id = #{groupId}
  AND s.first_message_id > gm.joined_after_id

SELECT s.id, s.group_id, s.requester_id, s.first_message_id, s.last_message_id,
       s.content, s.created_at
FROM im_group_summary s
JOIN im_group_member gm ON gm.group_id = s.group_id AND gm.user_id = #{userId}
WHERE s.group_id = #{groupId} AND s.first_message_id > gm.joined_after_id
ORDER BY s.id DESC LIMIT #{limit}
